	d := parsed[0].RemoteServer
	instanceName := parsed[0].RemoteObject.String
	templateName := parsed[1].String

	// Show the template
	template, err := d.GetInstanceTemplateFile(instanceName, templateName)
	if err != nil {
		return err
	}

	content, err := io.ReadAll(template)
	if err != nil {
