	flagFormat  string
	flagColumns string
}

var cmdNetworkIntegrationListUsage = u.Usage{u.RemoteColonOpt}

func (c *cmdNetworkIntegrationList) command() *cobra.Command {
	cmd := &cobra.Command{}
	cmd.Use = cli.U("list", cmdNetworkIntegrationListUsage...)
	cmd.Aliases = []string{"ls"}
