// Attach.
type cmdStorageVolumeAttach struct {
	global        *cmdGlobal
	storage       *cmdStorage
	storageVolume *cmdStorageVolume

	flagCreate bool
}

var cmdStorageVolumeAttachUsage = u.Usage{u.Pool.Remote(), u.Volume, u.Instance, u.NewName(u.Device).Optional(u.Path.Optional())}

func (c *cmdStorageVolumeAttach) command() *cobra.Command {
	cmd := &cobra.Command{}
	cmd.Use = cli.U("attach", cmdStorageVolumeAttachUsage...)
	cmd.Short = i18n.G("Attach new custom storage volumes to instances")
	cmd.Long = cli.FormatSection(color.DescriptionPrefix, i18n.G(
		`Attach new custom storage volumes to instances`,
	))

	cli.AddBoolFlag(cmd.Flags(), &c.flagCreate, "create", i18n.G("Create the custom storage volume if it doesn't already exist"))

	cmd.RunE = c.run

	cmd.ValidArgsFunction = func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		if len(args) == 0 {
			return c.global.cmpStoragePools(toComplete)
		}

		if len(args) == 1 {
			return c.global.cmpStoragePoolVolumes(args[0])
		}

		if len(args) == 2 {
			return c.global.cmpInstanceNamesFromRemote(args[0])
		}

		return nil, cobra.ShellCompDirectiveNoFileComp
	}

	return cmd
}

func (c *cmdStorageVolumeAttach) run(cmd *cobra.Command, args []string) error {
	parsed, err := c.global.Parse(cmdStorageVolumeAttachUsage, cmd, args)
	if err != nil {
		return err
	}

	d := parsed[0].RemoteServer
	poolName := parsed[0].RemoteObject.String
	volName := parsed[1].String
	instanceName := parsed[2].String
	devName := volName
	devPath := ""
	if !parsed[3].Skipped {
		devName = parsed[3].List[0].String
		devPath = parsed[3].List[1].String
	}

	reverter := revert.New()
	defer reverter.Fail()

	// If requested, create the storage volume if it doesn't already exist.
	if c.flagCreate {
		_, _, err := d.GetStoragePoolVolume(poolName, "custom", volName)
		if err != nil {
			if !api.StatusErrorCheck(err, http.StatusNotFound) {
				return err
			}

			// Default to a filesystem volume but use a block volume when attaching to a
			// virtual machine without a target path.
			contentType := "filesystem"
			if devPath == "" {
				inst, _, err := d.GetInstance(instanceName)
				if err != nil {
					return err
				}

				if inst.Type == "virtual-machine" {
					contentType = "block"
				}
			}

			vol := api.StorageVolumesPost{
				Name:        volName,
				Type:        "custom",
				ContentType: contentType,
			}

			err = d.CreateStoragePoolVolume(poolName, vol)
			if err != nil {
				return err
			}

			reverter.Add(func() {
				_ = d.DeleteStoragePoolVolume(poolName, "custom", volName)
			})
		}
	}

	// Prepare the instance's device entry
	device := map[string]string{
		"type":   "disk",
		"pool":   poolName,
		"source": volName,
		"path":   devPath,
	}

	// Add the device to the instance
	err = instanceDeviceAdd(d, instanceName, devName, device)
	if err != nil {
		return err
	}

	reverter.Success()

	return nil
}

