// Delete.
type cmdWarningDelete struct {
	global  *cmdGlobal
	warning *cmdWarning

	flagAll bool
}

var cmdWarningDeleteUsage = u.Usage{u.Either(u.WarningUUID.Remote().List(1), u.Sequence(u.Flag("all"), u.RemoteColonOpt))}

func (c *cmdWarningDelete) command() *cobra.Command {
	cmd := &cobra.Command{}
	cmd.Use = cli.U("delete", cmdWarningDeleteUsage...)
	cmd.Aliases = []string{"rm", "remove"}
	cmd.Short = i18n.G("Delete warnings")
	cmd.Long = cli.FormatSection(color.DescriptionPrefix, i18n.G(`Delete warnings`))

	cli.AddBoolFlag(cmd.Flags(), &c.flagAll, "all|a", i18n.G("Delete all warnings"))

	cmd.RunE = c.run

	return cmd
}

func (c *cmdWarningDelete) run(cmd *cobra.Command, args []string) error {
	parsed, err := c.global.Parse(cmdWarningDeleteUsage, cmd, args)
	if err != nil {
		return err
	}

	var errs []error

	if c.flagAll {
		if parsed[0].BranchID != 1 {
			return errors.New(i18n.G("--all cannot be used together with other arguments"))
		}

		d := parsed[0].List[1].RemoteServer
		allWarnings, err := d.GetWarnings()
		if err != nil {
			return err
		}

		for _, warning := range allWarnings {
			err = d.DeleteWarning(warning.UUID)
			if err != nil {
				errs = append(errs, err)
			}
		}
	} else {
		for _, p := range parsed[0].List {
			d := p.RemoteServer
			warningUUID := p.RemoteObject.String

			// Delete warnings
			err = d.DeleteWarning(warningUUID)
			if err != nil {
				errs = append(errs, err)
			}
		}
	}

	if len(errs) > 0 {
		return errors.Join(errs...)
	}

	return nil
}//go:build !windows

package main

import (
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"sync"

	"github.com/google/uuid"
	"github.com/spf13/cobra"

	"github.com/lxc/incus/v7/internal/i18n"
	"github.com/lxc/incus/v7/shared/util"
)

func (c *cmdWebui) run(cmd *cobra.Command, args []string) error {
	parsed, err := c.global.Parse(cmdWebuiUsage, cmd, args)
	if err != nil {
		return err
	}

	d := parsed[0].RemoteServer

	// Create localhost socket.
	server, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return fmt.Errorf("Unable to setup TCP socket: %w", err)
	}

	// Get the connection info.
	info, err := d.GetConnectionInfo()
	if err != nil {
		return err
	}

	uri, err := url.Parse(info.URL)
	if err != nil {
		return err
	}

	// Check that the target supports the UI.
	req, err := http.NewRequest("GET", fmt.Sprintf("%s/ui/", info.URL), nil)
	if err != nil {
		return err
	}

	resp, err := d.DoHTTP(req)
	if err != nil {
		return err
	}

	if resp.Body != nil {
		_ = resp.Body.Close()
	}

	if resp.StatusCode == http.StatusNotFound {
		return errors.New(i18n.G("The server doesn't have a web UI installed"))
	}

	// Enable keep-alive for proxied connections.
	httpClient, err := d.GetHTTPClient()
	if err != nil {
		return err
	}

	httpTransport, ok := httpClient.Transport.(*http.Transport)
	if ok {
		httpTransport.DisableKeepAlives = false
	}

	// Get server info.
	api10, api10Etag, err := d.GetServer()
	if err != nil {
		return err
	}

	// Generate credentials.
	token := uuid.New().String()

	// Handle inbound connections.
	transport := remoteProxyTransport{
		s:       d,
		baseURL: uri,
	}

	connections := uint64(0)
	transactions := uint64(0)

	handler := remoteProxyHandler{
		s:         d,
		transport: transport,
		api10:     api10,
		api10Etag: api10Etag,

		mu:           &sync.RWMutex{},
		connections:  &connections,
		transactions: &transactions,

		token: token,
		url:   "http://" + server.Addr().String(),
	}

	// Print address.
	uiURL := fmt.Sprintf("http://%s/ui?auth_token=%s", server.Addr().String(), token)
	fmt.Printf(i18n.G("Web server running at: %s")+"\n", uiURL)

	// Attempt to automatically open the web browser.
	_ = util.OpenBrowser(uiURL)

	// Start the server.
	err = http.Serve(server, handler)
	if err != nil {
		return err
	}

	return nil
}//go:build windows

