import (
	"encoding/json"
	"fmt"
	"strconv"
)

// DevicesMap type is used to hold incus devices configurations. In contrast to
// plain map[string]map[string]string it provides unmarshal methods for JSON and
// YAML, which gracefully handle numbers and bools.
//
// swagger:model
// swagger:type object
//
// Example: {"eth0": {"network": "incusbr0", "type": "nic"}}
type DevicesMap map[string]map[string]string

// Backwards compatibility tests.
var (
	_ map[string]map[string]string = DevicesMap{}
	_ DevicesMap                   = map[string]map[string]string{}
)

// UnmarshalJSON implements json.Unmarshaler interface.
func (m *DevicesMap) UnmarshalJSON(data []byte) error {
	var raw map[string]any

	err := json.Unmarshal(data, &raw)
	if err != nil {
		return fmt.Errorf("JSON data not valid for DevicesMap: %w", err)
	}

	return m.fromMapStringAny(raw)
}

// UnmarshalYAML implements yaml.Unmarshaler interface.
func (m *DevicesMap) UnmarshalYAML(unmarshal func(any) error) error {
	var raw map[string]any
	err := unmarshal(&raw)
	if err != nil {
		return fmt.Errorf("YAML data not valid for DevicesMap: %w", err)
	}

	return m.fromMapStringAny(raw)
}

func (m *DevicesMap) fromMapStringAny(raw map[string]any) error {
	if raw == nil {
		return nil
	}

	result := *m
	if result == nil {
		result = make(DevicesMap, len(raw))
	}

	for k, v := range raw {
		switch val := v.(type) {
		case map[string]any:
			res, err := fromMapStringAnyInner(val, result[k])
			if err != nil {
				return fmt.Errorf("inner type for %q: %w", k, err)
			}

			result[k] = res

		case map[any]any:
			mapStr := make(map[string]any, len(val))
			for key, value := range val {
				strKey, ok := key.(string)
				if !ok {
					return fmt.Errorf(`inner key "%v" is not a string`, key)
				}

				mapStr[strKey] = value
			}

			res, err := fromMapStringAnyInner(mapStr, result[k])
			if err != nil {
				return fmt.Errorf("inner type for %q: %w", k, err)
			}

			result[k] = res

		default:
			return fmt.Errorf("type %T is not supported in %T", v, m)
		}
	}

	*m = result

	return nil
}

func fromMapStringAnyInner(raw map[string]any, dest map[string]string) (map[string]string, error) {
	if dest == nil {
		dest = make(map[string]string, len(raw))
	}

	for k, v := range raw {
		switch val := v.(type) {
		case string:
			dest[k] = val

		case int:
			dest[k] = strconv.FormatInt(int64(val), 10)

		case uint64:
			dest[k] = strconv.FormatUint(val, 10)

		case float64:
			if val == float64(int64(val)) {
				dest[k] = strconv.FormatInt(int64(val), 10)
			} else {
				dest[k] = strconv.FormatFloat(val, 'g', -1, 64)
			}

		case bool:
			dest[k] = strconv.FormatBool(val)

		case nil:
			dest[k] = ""

		default:
			return nil, fmt.Errorf("type %T is not supported as inner type for %T", v, DevicesMap{})
		}
	}

	return dest, nil
}// Package api contains Go structs for all API objects
//
// # Overview
//
// This package has Go structs for every API object, all the various
// structs are named after the object they represent and some variations of
// those structs exist for initial object creation, object update and
// object retrieval.
//
// A few convenience functions are also tied to those structs which let
// you convert between the various strucs for a given object and also query
// some of the more complex metadata available.
package apipackage api

import (
	"errors"
	"fmt"
	"net/http"
	"slices"
)

// StatusErrorf returns a new StatusError containing the specified status and message.
func StatusErrorf(status int, format string, a ...any) StatusError {
	var msg string
	if len(a) > 0 {
		msg = fmt.Sprintf(format, a...)
	} else {
		msg = format
	}

	return StatusError{
		status: status,
		msg:    msg,
	}
}

// StatusError error type that contains an HTTP status code and message.
type StatusError struct {
	status int
	msg    string
}

// Error returns the error message or the http.StatusText() of the status code if message is empty.
func (e StatusError) Error() string {
	if e.msg != "" {
		return e.msg
	}

	return http.StatusText(e.status)
}

// Status returns the HTTP status code.
func (e StatusError) Status() int {
	return e.status
}

// StatusErrorMatch checks if err was caused by StatusError. Can optionally also check whether the StatusError's
// status code matches one of the supplied status codes in matchStatus.
// Returns the matched StatusError status code and true if match criteria are met, otherwise false.
func StatusErrorMatch(err error, matchStatusCodes ...int) (int, bool) {
	var statusErr StatusError

	if errors.As(err, &statusErr) {
		statusCode := statusErr.Status()

		if len(matchStatusCodes) <= 0 {
			return statusCode, true
		}

		if slices.Contains(matchStatusCodes, statusCode) {
			return statusCode, true
		}
	}

	return -1, false
}

// StatusErrorCheck returns whether or not err was caused by a StatusError and if it matches one of the
// optional status codes.
func StatusErrorCheck(err error, matchStatusCodes ...int) bool {
	_, found := StatusErrorMatch(err, matchStatusCodes...)
	return found
}package api

