}

func TestWithQuery(t *testing.T) {
	tests := []struct {
		name          string
		key           string
		value         string
		expectedKey   string
		expectedValue string
	}{
		{
			name:          "simple query",
			key:           "foo",
			value:         "bar",
			expectedKey:   "foo",
			expectedValue: "bar",
		},
		{
			name:          "empty value",
			key:           "empty",
			value:         "",
			expectedKey:   "empty",
			expectedValue: "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			u := NewURL().WithQuery(tt.key, tt.value)
			query := u.Query()

			if !query.Has(tt.expectedKey) {
				t.Errorf("Expected query to have key %q", tt.expectedKey)
			}

			if query.Get(tt.expectedKey) != tt.expectedValue {
				t.Errorf("Expected value %q for key %q, got %q", tt.expectedValue, tt.expectedKey, query.Get(tt.expectedKey))
			}
		})
	}

	// Test multiple query parameters
	t.Run("multiple query parameters", func(t *testing.T) {
		u := NewURL().
			WithQuery("foo", "bar").
			WithQuery("recursion", "1")

		query := u.Query()
		if query.Get("foo") != "bar" {
			t.Errorf("Expected foo=bar, got %q", query.Get("filter"))
		}

		if query.Get("recursion") != "1" {
			t.Errorf("Expected recursion=1, got %q", query.Get("recursion"))
		}
	})
}

func TestURLString(t *testing.T) {
	tests := []struct {
		name     string
		setup    func() *URL
		expected string
	}{
		{
			name: "full URL with all components",
			setup: func() *URL {
				return NewURL().
					Scheme("https").
					Host("example.com").
					Path("1.0", "networks", "test-network").
					Project("my-project").
					Target("member1")
			},
			expected: "https://example.com/1.0/networks/test-network?project=my-project&target=member1",
		},
		{
			name: "URL with encoded path",
			setup: func() *URL {
				return NewURL().
					Scheme("https").
					Host("example.com").
					Path("1.0", "networks", "name-with-/-in-it")
			},
			expected: "https://example.com/1.0/networks/name-with-%2F-in-it",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			u := tt.setup()
			actual := u.String()
			if actual != tt.expected {
				t.Errorf("Expected URL %q, got %q", tt.expected, actual)
			}
		})
	}
}package api

import (
	"net/url"
	"strings"
)

// URL represents an endpoint for the REST API.
type URL struct {
	url.URL
}

// NewURL creates a new URL.
func NewURL() *URL {
	return &URL{}
}

// Scheme sets the scheme of the URL.
func (u *URL) Scheme(scheme string) *URL {
	u.URL.Scheme = scheme

	return u
}

// Host sets the host of the URL.
func (u *URL) Host(host string) *URL {
	u.URL.Host = host

	return u
}

// Path sets the path of the URL from one or more path parts.
// It appends each of the pathParts (escaped using url.PathEscape) prefixed with "/" to the URL path.
func (u *URL) Path(pathParts ...string) *URL {
	var path, rawPath strings.Builder

	for _, pathPart := range pathParts {
		// Generate unencoded path.
		path.WriteString("/") // Build an absolute URL.
		path.WriteString(pathPart)

		// Generate encoded path hint (this will be used by u.URL.EncodedPath() to decide its methodology).
		rawPath.WriteString("/") // Build an absolute URL.
		rawPath.WriteString(url.PathEscape(pathPart))
	}

	u.URL.Path = path.String()
	u.RawPath = rawPath.String()

	return u
}

// Project sets the "project" query parameter in the URL if the projectName is not empty or "default".
func (u *URL) Project(projectName string) *URL {
	if projectName != "default" && projectName != "" {
		queryArgs := u.Query()
		queryArgs.Add("project", projectName)
		u.RawQuery = queryArgs.Encode()
	}

	return u
}

// Target sets the "target" query parameter in the URL if the clusterMemberName is not empty and not "none".
func (u *URL) Target(clusterMemberName string) *URL {
	if clusterMemberName != "" && clusterMemberName != "none" {
		queryArgs := u.Query()
		queryArgs.Add("target", clusterMemberName)
		u.RawQuery = queryArgs.Encode()
	}

	return u
}

// WithQuery adds a given query parameter with its value to the URL.
func (u *URL) WithQuery(key string, value string) *URL {
	queryArgs := u.Query()
	queryArgs.Add(key, value)
	u.RawQuery = queryArgs.Encode()

	return u
}

// Fragment sets the fragment of the URL.
func (u *URL) Fragment(fragment string) *URL {
	u.URL.Fragment = fragment

	return u
}package api

import (
	"time"
)

// Warning represents a warning entry.
//
// swagger:model
//
// API extension: warnings.
type Warning struct {
	WarningPut `yaml:",inline"`

	// UUID of the warning
	// Example: e9e9da0d-2538-4351-8047-46d4a8ae4dbb
	UUID string `json:"uuid" yaml:"uuid"`

	// What cluster member this warning occurred on
	// Example: server01
	Location string `json:"location" yaml:"location"`

	// The project the warning occurred in
	// Example: default
	Project string `json:"project" yaml:"project"`

	// Type type of warning
	// Example: Couldn't find CGroup
	Type string `json:"type" yaml:"type"`

	// The number of times this warning occurred
	// Example: 1
	Count int `json:"count" yaml:"count"`

	// The first time this warning occurred
	// Example: 2021-03-23T17:38:37.753398689-04:00
	FirstSeenAt time.Time `json:"first_seen_at" yaml:"first_seen_at"`

	// The last time this warning occurred
	// Example: 2021-03-23T17:38:37.753398689-04:00
	LastSeenAt time.Time `json:"last_seen_at" yaml:"last_seen_at"`

	// The warning message
	// Example: Couldn't find the CGroup blkio.weight, disk priority will be ignored
	LastMessage string `json:"last_message" yaml:"last_message"`

	// The severity of this warning
	// Example: low
	Severity string `json:"severity" yaml:"severity"`

	// The entity affected by this warning
	// Example: /1.0/instances/c1?project=default
	EntityURL string `json:"entity_url" yaml:"entity_url"`
}

// WarningPut represents the modifiable fields of a warning.
//
// swagger:model
//
// API extension: warnings.
type WarningPut struct {
	// Status of the warning (new, acknowledged, or resolved)
	// Example: new
	Status string `json:"status" yaml:"status"`
}
